43	// because a fake that ignores expectations cannot fail the way the broker does.
44	func (f *fakeDLQPublisher) PublishMsg(_ context.Context, m *nats.Msg, _ ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
45		if f.err != nil {
46			return nil, f.err
47		}
48		if want := m.Header.Get(jetstream.ExpectedStreamHeader); want != "" && want != dlqStreamName {
49			return nil, &jetstream.APIError{ErrorCode: 10060, Code: 400,
50				Description: fmt.Sprintf("expected stream does not match (%s)", want)}
51		}
52		// Dedupe the way JetStream does: on Nats-Msg-Id alone, STREAM-wide across every
53		// subject, returning a SUCCESSFUL PubAck marked Duplicate and storing nothing.
54		// Captured copies no longer carry an ID, so this never fires for them — it is
55		// kept as the GUARD that makes that fact testable. Reintroduce a dedupe identity
56		// and the "one record per capture" tests here start failing, which is exactly the
57		// silent suppression the no-dedupe decision exists to prevent.
58		if id := m.Header.Get(jetstream.MsgIDHeader); id != "" {
59			if f.seenIDs == nil {
60				f.seenIDs = map[string]bool{}
61			}
62			if f.seenIDs[id] {
63				return &jetstream.PubAck{Stream: dlqStreamName, Duplicate: true}, nil
64			}
65			f.seenIDs[id] = true
66		}
67		f.msgs = append(f.msgs, m)
68		return &jetstream.PubAck{Stream: dlqStreamName, Sequence: uint64(len(f.msgs))}, nil
